package com.learnagent.job;import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;@RestController@RequestMapping("/api/jobs")public class AgentJobController{private final AgentJobService service;public AgentJobController(AgentJobService service){this.service=service;}@GetMapping public List<AgentJob>list(){return service.list();}@GetMapping("/{id}")public AgentJob get(@PathVariable UUID id){return service.get(id);}@GetMapping("/events")public SseEmitter events(){return service.subscribe();}}
